// Extract handles - Notion Simplify mode flattens the structure
const creators = $input.all().map(item => {
  const handle = item.json.property_handle || '';
  return handle.replace('@', '');
}).filter(h => h.length > 0);

// Calculate 30 days ago for date filter
const since = new Date();
since.setDate(since.getDate() - 30);
const sinceStr = since.toISOString().split('T')[0];

// Query ONE creator at a time for full coverage
const chunkSize = 1;
const chunks = [];
for (let i = 0; i < creators.length; i += chunkSize) {
  chunks.push(creators.slice(i, i + chunkSize));
}

return chunks.map(chunk => ({
  json: {
    handles: chunk,
    query: chunk.map(h => `from:${h}`).join(' OR ') + ` -filter:replies -filter:retweets since:${sinceStr}`
  }
}));

const results = [];

const ratingMap = {
  1: '⭐',
  2: '⭐⭐',
  3: '⭐⭐⭐',
  4: '⭐⭐⭐⭐',
  5: '⭐⭐⭐⭐⭐'
};

for (const item of $input.all()) {
  // AI output from current item
  const aiOutput = item.json.output || item.json.text || {};

  // Original tweet data from Edit Fields (FLAT structure)
  const tweet = $('Edit Fields').item.json;

  // Parse AI output
  let analysis = {};
  try {
    if (typeof aiOutput === 'string') {
      const cleaned = aiOutput.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
      analysis = JSON.parse(cleaned);
    } else if (typeof aiOutput === 'object') {
      analysis = aiOutput;
    }
  } catch (e) {
    analysis = {
      // Fallbacks in case of error
      postTitle: (tweet.text || '').substring(0, 50),
      category: 'Tech/AI',
      hookType: 'Story',
      format: 'Short',
      rating: '⭐⭐⭐',
      whyItWorks: 'Unable to parse AI analysis',
      stealablePattern: '',
      tweetStructure: '', // Fallback for new field
      shortDescription: (tweet.text || '').substring(0, 100)
    };
  }

  // 1. Handle Rating (Number -> Stars)
  let rating = analysis.rating || '⭐⭐⭐';
  if (typeof rating === 'number') {
    rating = ratingMap[rating] || '⭐⭐⭐';
  }

  // 2. Handle Category (String -> Array for Multi-Select)
  let categories = analysis.category || 'Tech/AI';
  if (typeof categories === 'string') {
    categories = categories.split(',').map(c => c.trim());
  } else if (!Array.isArray(categories)) {
     categories = ['Tech/AI']; 
  }

  results.push({
    json: {
      // Original tweet data
      postUrl: tweet.postUrl,
      postContent: tweet.text,
      author: `@${tweet.authorHandle}`,
      platform: 'X',

      // Metrics - FORCED TO NUMBERS using parseInt
      likes: parseInt(tweet.likes) || 0,
      retweets: parseInt(tweet.retweets) || 0,
      replies: parseInt(tweet.replies) || 0,
      bookmarks: parseInt(tweet.bookmarks) || 0,
      views: parseInt(tweet.views) || 0,

      // AI Analysis
      postTitle: analysis.postTitle || analysis.shortDescription || (tweet.text || '').substring(0, 50),
      category: categories,
      hookType: analysis.hookType || 'Story',
      format: analysis.format || 'Short',
      rating: rating,
      whyItWorks: analysis.whyItWorks || '',
      stealablePattern: analysis.stealablePattern || '',
      shortDescription: analysis.shortDescription || '',
      tweetStructure: analysis.tweetStructure || '', // ADDED THIS LINE

      // Metadata
      addedDate: new Date().toISOString().split('T')[0]
    }
  });
}

return results;

// ========== CONFIGURABLE THRESHOLDS ==========
const MIN_VIEWS = 3000;        // Skip tweets under 3k views
const MIN_BOOKMARKS = 10;      // Skip tweets under 10 bookmarks
const TOP_COUNT = 100;         // Keep top 100 tweets (MAXIMUM COVERAGE)
// =============================================

// Get aggregated tweets from Aggregate node
const aggregatedItems = $('Aggregate').all();
const allTweets = aggregatedItems.flatMap(item => {
  const data = item.json.data || [];
  return data.flatMap(d => d.tweets || []);
});

// Get existing URLs from Notion for deduplication
const existingUrls = new Set(
  $('Notion: Get Existing Posts').all()
    .map(i => i.json.property_post_url || i.json.url || '')
    .filter(url => url.length > 0)
);

// Filter, calculate Score, SAFTY CHECK, sort, and get top 100
const processed = allTweets
  .filter(t => {
    const postUrl = `https://x.com/${t.author?.userName}/status/${t.id}`;
    const isNew = !existingUrls.has(postUrl);

    // Safety: Ensure numbers are numbers before comparing
    const views = parseInt(t.viewCount) || 0;
    const bookmarks = parseInt(t.bookmarkCount) || 0;

    const meetsMinViews = views >= MIN_VIEWS;
    const meetsMinBookmarks = bookmarks >= MIN_BOOKMARKS;

    return isNew && meetsMinViews && meetsMinBookmarks;
  })
  .map(t => {
     // Safety: Force all metrics to Integers (Fixes Notion 400 Error)
     const likes = parseInt(t.likeCount) || 0;
     const retweets = parseInt(t.retweetCount) || 0;
     const replies = parseInt(t.replyCount) || 0;
     const bookmarks = parseInt(t.bookmarkCount) || 0;
     const views = parseInt(t.viewCount) || 0;

     // HYBRID VIRAL SCORE FORMULA
     const score = 
       (bookmarks * 10) + 
       (retweets * 5) + 
       (replies * 2) + 
       (Math.floor(views / 1000));

     return {
       ...t,
       postUrl: `https://x.com/${t.author?.userName}/status/${t.id}`,
       authorUserName: t.author?.userName || '',
       viralScore: score, // IMPACT (Sort by this)
       bookmarkRate: (bookmarks / Math.max(views, 1)) * 100, // EFFICIENCY (Reference)

       // Explicitly overwrite raw strings with safe numbers
       likeCount: likes,
       retweetCount: retweets,
       replyCount: replies,
       bookmarkCount: bookmarks,
       viewCount: views
     };
  })
  .sort((a, b) => b.viralScore - a.viralScore)
  .slice(0, TOP_COUNT);

// Must return array of objects
if (processed.length === 0) {
  return [{ json: { message: 'No new tweets matched filters', count: 0, filters: { MIN_VIEWS, MIN_BOOKMARKS } } }];
}

return processed.map(t => ({ json: t }));
